import y2026 from '@/data/patro/2026.json';
import y2027 from '@/data/patro/2027.json';

// Generated by scripts/patro/generate.mjs (Lahiri panchang for Darjeeling, IST). Minutes are since IST midnight.
export interface PatroDay {
  d: string; // YYYY-MM-DD
  wd: number; // 0 = Sunday
  bs: [number, number, number]; // BS year, month (1-12), day
  sr: number; ss: number; mr: number | null; ms: number | null;
  t: [number, number][]; n: [number, number][]; y: [number, number][]; k: [number, number][]; // [index, end minute]
  lm: number; // amanta lunar month index, 0 = Chaitra
  adhik: 0 | 1;
  rk: [number, number]; ym: [number, number]; gk: [number, number];
  ab: [number, number] | null; bm: [number, number];
}
export interface PatroEvent { id: string; date: string }
export interface PatroYear { year: number; place: string; days: PatroDay[]; events: PatroEvent[] }

const YEARS: Record<number, PatroYear> = {
  2026: y2026 as unknown as PatroYear,
  2027: y2027 as unknown as PatroYear,
};
export const FIRST_MONTH = { year: 2026, month: 1 };
export const LAST_MONTH = { year: 2027, month: 12 };

export const hasMonth = (y: number, m: number) =>
  !!YEARS[y] && m >= 1 && m <= 12 &&
  (y * 12 + m) >= (FIRST_MONTH.year * 12 + FIRST_MONTH.month) && (y * 12 + m) <= (LAST_MONTH.year * 12 + LAST_MONTH.month);

export function getMonth(y: number, m: number): PatroDay[] {
  const prefix = `${y}-${String(m).padStart(2, '0')}-`;
  return YEARS[y].days.filter((d) => d.d.startsWith(prefix));
}
export function allEvents(): PatroEvent[] {
  return Object.values(YEARS).flatMap((y) => y.events).sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));
}
export function allMonths(): { year: number; month: number }[] {
  const out: { year: number; month: number }[] = [];
  for (let y = FIRST_MONTH.year; y <= LAST_MONTH.year; y++) for (let m = 1; m <= 12; m++) if (hasMonth(y, m)) out.push({ year: y, month: m });
  return out;
}
export const ymSlug = (y: number, m: number) => `${y}-${String(m).padStart(2, '0')}`;

/** today's year/month in IST */
export function currentIstMonth(now = Date.now()): { year: number; month: number } {
  const t = new Date(now + 330 * 60000);
  let y = t.getUTCFullYear(), m = t.getUTCMonth() + 1;
  if (!hasMonth(y, m)) { const c = y * 12 + m < FIRST_MONTH.year * 12 + FIRST_MONTH.month ? FIRST_MONTH : LAST_MONTH; y = c.year; m = c.month; }
  return { year: y, month: m };
}
